//! Named structured operations generated from MLIR's
//! `LinalgNamedStructuredOps.yaml`.
//!
//! Do not edit by hand. Each operation stores no body region: its scalar
//! computation is implied by the name, as in MLIR's custom assembly form.
//! Operands are the `ins` (tensors or scalars) followed by one `outs` tensor;
//! the result has the `outs` type.
// @generated by gen_named.py

use crate::{
    attributes::{I64ArrayAttr, IteratorType, TypeFn, TypeFnAttr},
    support::*,
};
use pliron::{
    common_traits::Verify,
    context::{Context, Ptr},
    derive::pliron_op,
    op::Op,
    operation::Operation,
    result::Result,
    r#type::Typed,
    value::Value,
};
use stablehlo::attributes::{AffineBinaryOp, AffineExpr, AffineMap};

const P: IteratorType = IteratorType::Parallel;
const R: IteratorType = IteratorType::Reduction;

/// Coefficient of a loop dimension in an indexing expression.
#[derive(Clone, Copy)]
enum Coef {
    One,
    Stride(usize),
    Dilation(usize),
}

use Coef::{Dilation, One, Stride};

/// Indexing of one operand.
#[derive(Clone, Copy)]
enum Arg {
    /// One expression per operand dimension, each a sum of `dim * coef` terms.
    Map(&'static [&'static [(usize, Coef)]]),
    /// Rank-polymorphic identity over the output rank.
    Identity,
    /// Rank-0 operand of a rank-polymorphic operation.
    Scalar,
}

/// Static description of a named operation.
struct Spec {
    args: &'static [Arg],
    iterators: &'static [IteratorType],
    /// Length of the `strides`/`dilations` attributes; 0 when the op has none.
    window: usize,
    /// Whether the iteration space is the output rank (`copy`, `fill`).
    poly: bool,
}

impl Spec {
    fn loops(&self, output_rank: usize) -> usize {
        if self.poly {
            output_rank
        } else {
            self.iterators.len()
        }
    }

    fn iterator_types(&self, output_rank: usize) -> Vec<IteratorType> {
        if self.poly {
            vec![IteratorType::Parallel; output_rank]
        } else {
            self.iterators.to_vec()
        }
    }

    fn maps(&self, output_rank: usize, strides: &[i64], dilations: &[i64]) -> Vec<AffineMap> {
        let loops = self.loops(output_rank);
        let coef = |c: Coef| match c {
            Coef::One => 1,
            Coef::Stride(i) => strides.get(i).copied().unwrap_or(1),
            Coef::Dilation(i) => dilations.get(i).copied().unwrap_or(1),
        };
        self.args
            .iter()
            .map(|arg| {
                let results = match arg {
                    Arg::Identity => (0..loops).map(AffineExpr::dimension).collect(),
                    Arg::Scalar => Vec::new(),
                    Arg::Map(exprs) => exprs
                        .iter()
                        .map(|terms| {
                            terms
                                .iter()
                                .map(|&(dim, c)| match coef(c) {
                                    1 => AffineExpr::dimension(dim),
                                    k => AffineExpr::binary(
                                        AffineBinaryOp::Mul,
                                        AffineExpr::dimension(dim),
                                        AffineExpr::constant(k),
                                    ),
                                })
                                .reduce(|l, r| AffineExpr::binary(AffineBinaryOp::Add, l, r))
                                .unwrap_or_else(|| AffineExpr::constant(0))
                        })
                        .collect(),
                };
                AffineMap {
                    dimensions: loops,
                    symbols: 0,
                    results,
                }
            })
            .collect()
    }
}

/// Returns the output rank, or 0 when the last operand is not a ranked tensor.
fn output_rank(ctx: &Context, op: Ptr<Operation>) -> usize {
    let ir = op.deref(ctx);
    let Some(last) = ir.operands().last() else {
        return 0;
    };
    ranked(ctx, last.get_type(ctx)).map_or(0, |(dims, _)| dims.len())
}

fn window_values(
    ctx: &Context,
    op: Ptr<Operation>,
    spec: &Spec,
    values: Option<Vec<i64>>,
    what: &'static str,
) -> Result<Vec<i64>> {
    match values {
        None => Ok(vec![1; spec.window]),
        Some(values) if values.len() == spec.window && values.iter().all(|&v| v > 0) => Ok(values),
        Some(_) => Err(fail(ctx, op, what)),
    }
}

fn verify_spec(
    ctx: &Context,
    op: Ptr<Operation>,
    spec: &Spec,
    strides: Option<Vec<i64>>,
    dilations: Option<Vec<i64>>,
) -> Result<()> {
    let inputs = spec.args.len() - 1;
    {
        let ir = op.deref(ctx);
        if ir.get_num_operands() != spec.args.len()
            || ir.get_num_results() != 1
            || ir.num_regions() != 0
        {
            return Err(fail(ctx, op, "operand, result, or region count mismatch"));
        }
    }
    verify_tensor_outputs(ctx, op, inputs..inputs + 1)?;
    let mut shapes = Vec::with_capacity(spec.args.len());
    for ty in operand_types(ctx, op) {
        let (dims, element) = ranked_or_scalar(ctx, ty)
            .ok_or_else(|| fail(ctx, op, "operands must be ranked tensors or scalars"))?;
        if !numeric(ctx, element) {
            return Err(fail(ctx, op, "operand elements must be numeric"));
        }
        shapes.push(dims);
    }
    let strides = window_values(
        ctx,
        op,
        spec,
        strides,
        "strides must have one positive entry per window dimension",
    )?;
    let dilations = window_values(
        ctx,
        op,
        spec,
        dilations,
        "dilations must have one positive entry per window dimension",
    )?;
    let rank = shapes[inputs].len();
    verify_indexing(
        ctx,
        op,
        &spec.maps(rank, &strides, &dilations),
        &shapes,
        spec.loops(rank),
    )?;
    Ok(())
}

macro_rules! named_common {
    ($struct:ident, $spec:ident, $inputs:literal) => {
        impl $struct {
            /// Allocates the operation; the result type is `init`'s type.
            pub fn new(ctx: &mut Context, inputs: Vec<Value>, init: Value) -> Self {
                let ty = init.get_type(ctx);
                let operands = inputs.into_iter().chain([init]).collect();
                Self {
                    op: Operation::new(
                        ctx,
                        Self::get_concrete_op_info(),
                        vec![ty],
                        operands,
                        vec![],
                        0,
                    ),
                }
            }
            /// Returns the `ins` operands.
            pub fn inputs(&self, ctx: &Context) -> Vec<Value> {
                self.get_operation()
                    .deref(ctx)
                    .operands()
                    .take($inputs)
                    .collect()
            }
            /// Returns the `outs` operand.
            pub fn init(&self, ctx: &Context) -> Value {
                self.get_operation().deref(ctx).get_operand($inputs)
            }
            /// Returns the result.
            pub fn result(&self, ctx: &Context) -> Value {
                self.get_operation().deref(ctx).get_result(0)
            }
            /// Returns the iterator types of the implied iteration space.
            pub fn iterator_types(&self, ctx: &Context) -> Vec<IteratorType> {
                $spec.iterator_types(output_rank(ctx, self.get_operation()))
            }
        }
    };
}

macro_rules! named_op {
    (plain $struct:ident, $name:literal, $spec:ident, $inputs:literal, $doc:literal) => {
        #[doc = $doc]
        #[pliron_op(
                            name = $name,
                            format = "operands(CharSpace(`,`)) attr_dict `:` typesig",
                            interfaces = [pliron::builtin::op_interfaces::OneResultInterface]
                        )]
        pub struct $struct;

        named_common!($struct, $spec, $inputs);

        impl $struct {
            /// Returns the indexing maps, one per operand.
            pub fn indexing_maps(&self, ctx: &Context) -> Vec<AffineMap> {
                $spec.maps(output_rank(ctx, self.get_operation()), &[], &[])
            }
        }

        impl Verify for $struct {
            fn verify(&self, ctx: &Context) -> Result<()> {
                verify_spec(ctx, self.get_operation(), &$spec, None, None)
            }
        }
    };
    (window $struct:ident, $name:literal, $spec:ident, $inputs:literal, $doc:literal) => {
        #[doc = $doc]
        ///
        /// `strides` and `dilations` default to all ones.
        #[pliron_op(
                            name = $name,
                            format = "operands(CharSpace(`,`)) attr_dict `:` typesig",
                            interfaces = [pliron::builtin::op_interfaces::OneResultInterface]
                        )]
        pub struct $struct;
        crate::pliron_arith::shared_attr!(
            $struct,
            super::ATTR_KEY_LINALG_STRIDES,
            I64ArrayAttr,
            get_attr_linalg_strides,
            set_attr_linalg_strides
        );
        crate::pliron_arith::shared_attr!(
            $struct,
            super::ATTR_KEY_LINALG_DILATIONS,
            I64ArrayAttr,
            get_attr_linalg_dilations,
            set_attr_linalg_dilations
        );

        named_common!($struct, $spec, $inputs);

        impl $struct {
            /// Sets the window strides.
            pub fn set_strides(&self, ctx: &Context, strides: Vec<i64>) {
                self.set_attr_linalg_strides(ctx, I64ArrayAttr::new(strides));
            }
            /// Sets the window dilations.
            pub fn set_dilations(&self, ctx: &Context, dilations: Vec<i64>) {
                self.set_attr_linalg_dilations(ctx, I64ArrayAttr::new(dilations));
            }
            /// Returns the window strides (all ones when absent).
            pub fn strides(&self, ctx: &Context) -> Vec<i64> {
                self.get_attr_linalg_strides(ctx)
                    .map_or_else(|| vec![1; $spec.window], |a| a.values.clone())
            }
            /// Returns the window dilations (all ones when absent).
            pub fn dilations(&self, ctx: &Context) -> Vec<i64> {
                self.get_attr_linalg_dilations(ctx)
                    .map_or_else(|| vec![1; $spec.window], |a| a.values.clone())
            }
            /// Returns the indexing maps with strides and dilations substituted.
            pub fn indexing_maps(&self, ctx: &Context) -> Vec<AffineMap> {
                $spec.maps(
                    output_rank(ctx, self.get_operation()),
                    &self.strides(ctx),
                    &self.dilations(ctx),
                )
            }
        }

        impl Verify for $struct {
            fn verify(&self, ctx: &Context) -> Result<()> {
                let strides = self.get_attr_linalg_strides(ctx).map(|a| a.values.clone());
                let dilations = self
                    .get_attr_linalg_dilations(ctx)
                    .map(|a| a.values.clone());
                verify_spec(ctx, self.get_operation(), &$spec, strides, dilations)
            }
        }
    };
    (cast $struct:ident, $name:literal, $spec:ident, $inputs:literal, $doc:literal) => {
        #[doc = $doc]
        ///
        /// `cast` defaults to [`TypeFn::CastSigned`].
        #[pliron_op(
                            name = $name,
                            format = "operands(CharSpace(`,`)) attr_dict `:` typesig",
                            interfaces = [pliron::builtin::op_interfaces::OneResultInterface]
                        )]
        pub struct $struct;
        crate::pliron_arith::shared_attr!(
            $struct,
            super::ATTR_KEY_LINALG_CAST,
            TypeFnAttr,
            get_attr_linalg_cast,
            set_attr_linalg_cast
        );

        named_common!($struct, $spec, $inputs);

        impl $struct {
            /// Sets the input conversion.
            pub fn set_cast(&self, ctx: &Context, cast: TypeFn) {
                self.set_attr_linalg_cast(ctx, TypeFnAttr::new(cast));
            }
            /// Returns the input conversion.
            pub fn cast(&self, ctx: &Context) -> TypeFn {
                self.get_attr_linalg_cast(ctx)
                    .map_or(TypeFn::CastSigned, |a| a.value)
            }
            /// Returns the indexing maps, one per operand.
            pub fn indexing_maps(&self, ctx: &Context) -> Vec<AffineMap> {
                $spec.maps(output_rank(ctx, self.get_operation()), &[], &[])
            }
        }

        impl Verify for $struct {
            fn verify(&self, ctx: &Context) -> Result<()> {
                verify_spec(ctx, self.get_operation(), &$spec, None, None)
            }
        }
    };
}

